tests.code:
cfg = load_config({"weight_col": "w"})
try:
    cfg.min_base = 1
except dataclasses.FrozenInstanceError:
    pass
else:
    raise AssertionError("assignment allowed")

for bad in (0, -5, "30"):
    try:
        load_config({"weight_col": "w", "min_base": bad})
    except ValueError:
        continue
    raise AssertionError(bad)

try:
    load_config({"weight_col": "w", "minbase": 30})
except TypeError:
    pass
else:
    raise AssertionError("typo accepted")

